package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addWeeks_TriageGen1Test {

    @Test
    public void testAddWeeks_PositiveValue() {
        // Initialize with a fixed date: 2023-01-01
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        int weeksToAdd = 2;

        dt.addWeeks(weeksToAdd);

        // 2023-01-01 + 2 weeks = 2023-01-15
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeks_NegativeValue() {
        // Initialize with a fixed date: 2023-01-15
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 0, 0, 0, 0);
        int weeksToAdd = -1;

        dt.addWeeks(weeksToAdd);

        // 2023-01-15 - 1 week = 2023-01-08
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(8, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeks_Zero() {
        // Initialize with a fixed date: 2023-05-20
        MutableDateTime dt = new MutableDateTime(2023, 5, 20, 12, 30, 0, 0);
        int weeksToAdd = 0;

        dt.addWeeks(weeksToAdd);

        // Date should remain unchanged
        assertEquals(2023, dt.getYear());
        assertEquals(5, dt.getMonthOfYear());
        assertEquals(20, dt.getDayOfMonth());
        assertEquals(12, dt.getHourOfDay());
        assertEquals(30, dt.getMinuteOfHour());
    }

    @Test
    public void testAddWeeks_CrossingMonthBoundary() {
        // January 28th, 2023
        MutableDateTime dt = new MutableDateTime(2023, 1, 28, 0, 0, 0, 0);
        int weeksToAdd = 1;

        dt.addWeeks(weeksToAdd);

        // Should move to February 4th, 2023
        assertEquals(2023, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(4, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeks_CrossingYearBoundary() {
        // December 25th, 2023
        MutableDateTime dt = new MutableDateTime(2023, 12, 25, 0, 0, 0, 0);
        int weeksToAdd = 2;

        dt.addWeeks(weeksToAdd);

        // Should move to January 8th, 2024
        assertEquals(2024, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(8, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeks_LargeValue() {
        // Start at epoch
        MutableDateTime dt = new MutableDateTime(0, 1, 1, 0, 0, 0, 0);
        // Add 52 weeks (approx 1 year)
        dt.addWeeks(52);

        // Verify it changed significantly
        assertTrue(dt.getYear() >= 1);
    }
}
